// Check that the loop generated by 'flatten' can be consumed by a loop
// associated directive ('omp for' / 'omp parallel for'), and that signed and
// unsigned induction variables generate signed/unsigned division.

// RUN: %clang_cc1 -verify -triple x86_64-pc-linux-gnu -std=c++20 -fopenmp -fopenmp-version=61 -emit-llvm %s -o - | FileCheck %s

// expected-no-diagnostics

#ifndef HEADER
#define HEADER

extern "C" void body(int, int);
extern "C" void ubody(unsigned, unsigned);

// 'omp for' worksharing over the flattened iteration space: the flattened loop
// uses a 64-bit induction variable for the variable-bound product trip count,
// so the worksharing loop is distributed with the 64-bit static-init call and
// the body recovers the logical counters via signed division/remainder.
//
// CHECK-LABEL: define {{.*}}void @wsfor(
// CHECK:   mul nsw i64
// CHECK:   call void @__kmpc_for_static_init_8(
// CHECK:   sdiv i64
// CHECK:   srem i64
// CHECK:   call void @body(
// CHECK:   call void @__kmpc_for_static_fini(
extern "C" void wsfor(int n, int m) {
#pragma omp for
#pragma omp flatten
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      body(i, j);
}

// 'omp parallel for' outlines the flattened loop and worksharing-distributes
// it.
//
// CHECK-LABEL: define {{.*}}void @pfor(
// CHECK:   call {{.*}}@__kmpc_fork_call(
// CHECK-LABEL: define internal void @pfor.omp_outlined(
// CHECK:   call void @__kmpc_for_static_init_8(
// CHECK:   sdiv i64
// CHECK:   srem i64
// CHECK:   call void @body(
extern "C" void pfor(int n, int m) {
#pragma omp parallel for
#pragma omp flatten
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      body(i, j);
}

// Unsigned induction variables produce unsigned division/remainder.
//
// CHECK-LABEL: define {{.*}}void @ufor(
// CHECK:   icmp ult i32 %{{.+}}, 63
// CHECK:   udiv i32 %{{.+}}, 9
// CHECK:   urem i32 %{{.+}}, 9
// CHECK:   call void @ubody(
extern "C" void ufor() {
#pragma omp flatten
  for (unsigned i = 0; i < 7u; ++i)
    for (unsigned j = 0; j < 9u; ++j)
      ubody(i, j);
}

#endif
